//==============================================================================
// CUSTOMIZATION DEFINES
//==============================================================================
#define LIGHTS 3
#define LAYERS 2
#define COMPLEXITY 2.0
#define BASE_COLOR vec3(0.2, 0.4, 0.6)
#define HIGHLIGHT_COLOR vec3(0.8, 0.9, 1.0)
#define GLOW_COLOR vec3(1.0, 0.7, 0.5)

//==============================================================================
// HASH AND NOISE FUNCTIONS
//==============================================================================
// Hash function for noise
float hash(vec2 p) {
    p = fract(p * vec2(234.34, 435.345));
    p += dot(p, p + 34.23);
    return fract(p.x * p.y);
}

// 2D noise function
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f); // Smooth interpolation

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float f = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
        f += amp * noise(p);
        p *= 2.0;
        amp *= 0.5;
    }
    return f;
}

//==============================================================================
// SDF FUNCTIONS
//==============================================================================
// Circular SDF
float sdCircle(vec2 p, float radius) {
    return length(p) - radius;
}

// Box SDF with adjustable roundness
float sdRoundedBox(vec2 p, vec2 size, float roundness) {
    vec2 d = abs(p) - size;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - roundness;
}

//==============================================================================
// COLOR FUNCTIONS
//==============================================================================
// Dynamic palette
vec3 palette(float t) {
    float mixFactor = sin(t * 2.0) * 0.5 + 0.5; // Smooth oscillation
    return mix(BASE_COLOR, HIGHLIGHT_COLOR, mixFactor);
}

//==============================================================================
// UTILITY FUNCTIONS
//==============================================================================
// Rotate a point by an angle
mat2 rotationMatrix(float angle) {
    return mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
}

// Glow function for soft edges
float glow(float dist, float radius, float intensity) {
    return exp(-pow(dist / radius, intensity));
}

//==============================================================================
// MAIN SHADER FUNCTION
//==============================================================================
void mainImage(out vec4 fragColor, vec2 fragCoord) {
    vec2 uv = COMPLEXITY * (2.0 * fragCoord.xy - iResolution.xy) / iResolution.y;
    vec3 finalColor = vec3(0.0);

    // Iterate over layers
    for (int layer = 0; layer < LAYERS; layer++) {
        float layerOffset = float(layer) * 0.5;

        // Iterate over lights
        for (int i = 0; i < LIGHTS; i++) {
            float timeOffset = float(i) * 3.14159 / float(LIGHTS) + layerOffset;
            vec2 offset = vec2(
                cos(iTime * 0.5 + timeOffset) * 0.3,
                sin(iTime * 0.4 + timeOffset) * 0.3
            );

            vec2 transformedUv = uv + offset;
            transformedUv *= rotationMatrix(iTime * 0.1 + float(i) * 0.2);

            // SDF shapes
            float circle = sdCircle(transformedUv, 0.4);
            float roundedBox = sdRoundedBox(transformedUv, vec2(0.5, 0.3), 0.1);
            float shapeSDF = min(circle, roundedBox);

            // Noise and glow effects
            float wave = fbm(transformedUv * 0.5 + iTime * 0.1) * 0.1;
            float glowEffect = glow(shapeSDF + wave, 0.05, 2.0);

            // Combine shape color and glow
            vec3 shapeColor = palette(float(i) / float(LIGHTS) + iTime * 0.1);
            finalColor += shapeColor * glowEffect * (1.0 - float(layer) * 0.2);
        }
    }

    // Background gradient
    vec3 background = mix(vec3(0.05, 0.05, 0.1), GLOW_COLOR, 0.1);
    finalColor = mix(background, finalColor, length(finalColor));

    // Post-processing effects
    finalColor *= 1.0 + 0.2 * sin(iTime + uv.xyx + vec3(0, 2, 4));
    finalColor += pow(finalColor, vec3(2.0)) * 0.3;

    // Vignette
    float vignette = length(uv * 0.5);
    finalColor *= smoothstep(1.5, 0.5, vignette);

    fragColor = vec4(pow(finalColor, vec3(0.8)), 1.0); // Gamma correction
}
